// Test plan docs are machine-generated (or hand-edited in a linked repo)
// markdown, not trusted HTML — marked renders markdown syntax safely on
// its own (text nodes are escaped internally), but by default passes
// literal inline/block HTML straight through. Overriding the html
// renderer to escape it instead closes that off without needing a second
// library (e.g. DOMPurify) just for this. HTML comments are the one
// exception: marked's own tokenizer already delimits them with a
// dedicated <!-- ... --> regex before this renderer ever sees the text,
// so a token that's wholly a comment is inert (browsers never execute or
// display comment contents) — passing it through unescaped also keeps
// the devlore:test-plan marker comment invisible, as testPlanDoc.ts
// intends.
// GitHub-style heading slugs, so the User Manual pane's internal links
// (e.g. "see [Linking a project](#linking-a-project)") have something to
// scroll to. Cleared before each marked.parse() call (see resetHeadingSlugs
// below) — the counter is what disambiguates repeated heading text within
// one document, so it must not carry over between separate parses.
const headingSlugCounts = new Map();

function resetHeadingSlugs() {
  headingSlugCounts.clear();
}

function slugifyHeading(text) {
  const base = text
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, "")
    .replace(/\s+/g, "-");
  const count = headingSlugCounts.get(base) || 0;
  headingSlugCounts.set(base, count + 1);
  return count === 0 ? base : `${base}-${count}`;
}

// docs/TEST_PLAN.md and docs/USER_MANUAL.md both open with a machine
// marker comment plus a "do not move, rename, or edit this file"
// blockquote (testPlanBanner()/userManualBanner() in src/lib) — that
// banner protects the file on GitHub, but once it's already being read
// inside Devlore's own UI it's pure noise, not something the reader needs
// to see. Stripped before rendering rather than hidden with CSS, so it
// never appears even for an instant.
const DEVLORE_BANNER_PATTERN = /^<!--[\s\S]*?-->\n>[^\n]*\n\n/;

function stripDoNotEditBanner(content) {
  return content.replace(DEVLORE_BANNER_PATTERN, "");
}

// Visualizer docs are the one place a fenced code block should become a
// diagram instead of literal text — a ```mermaid block is rendered into a
// <pre class="mermaid"> container that mermaid.run() (see loadVisualizer
// below) replaces with sanitized SVG after the HTML is inserted. The
// source text is escaped the same way the html renderer above escapes
// stray HTML: mermaid.run() reads it back via the element's textContent,
// which the browser decodes from these entities, so escaping here doesn't
// corrupt the diagram source — it only prevents it from being interpreted
// as markup before mermaid ever sees it.
function escapeForMermaidContainer(text) {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

marked.use({
  renderer: {
    html({ text }) {
      const trimmed = text.trim();
      if (trimmed.startsWith("<!--") && trimmed.endsWith("-->")) {
        return text;
      }
      return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    },
    heading({ tokens, depth }) {
      const text = this.parser.parseInline(tokens);
      const plainText = this.parser.parseInline(tokens, this.parser.textRenderer);
      const id = slugifyHeading(plainText);
      return `<h${depth} id="${id}">${text}</h${depth}>\n`;
    },
    code({ text, lang }) {
      if (lang === "mermaid") {
        return `<pre class="mermaid">${escapeForMermaidContainer(text)}</pre>\n`;
      }
      return false;
    },
  },
});

