// the class and remembers the choice.
const SIDEBAR_COLLAPSED_STORAGE_KEY = "devlore-sidebar-collapsed";

function setSidebarCollapsed(collapsed) {
  sidebarEl.classList.toggle("collapsed", collapsed);
  sidebarCollapseToggleEl.setAttribute("aria-expanded", String(!collapsed));
  sidebarCollapseToggleEl.setAttribute("aria-label", collapsed ? "Expand sidebar" : "Collapse sidebar");
  sidebarCollapseToggleEl.title = collapsed ? "Expand sidebar" : "Collapse sidebar";
  localStorage.setItem(SIDEBAR_COLLAPSED_STORAGE_KEY, String(collapsed));
}

