function effectiveTheme() {
  return document.documentElement.dataset.theme || (prefersDarkQuery.matches ? "dark" : "light");
}

// mermaid has no "light" theme name of its own — "default" is its light
// theme.
function mermaidTheme() {
  return effectiveTheme() === "dark" ? "dark" : "default";
}

function updateThemeToggleLabel() {
  themeToggleEl.textContent =
    effectiveTheme() === "dark" ? "☀️ Switch to light mode" : "🌙 Switch to dark mode";
}

function setTheme(theme) {
  document.documentElement.dataset.theme = theme;
  localStorage.setItem(THEME_STORAGE_KEY, theme);
  updateThemeToggleLabel();
}

themeToggleEl.addEventListener("click", () => {
  setTheme(effectiveTheme() === "dark" ? "light" : "dark");
  closeSettingsMenu();
});

