// Real incident, 2026-08-17: a chat question's "Asking Claude… Xs" bubble
// kept climbing past a minute with nothing happening — no error, no
// resolution, just an indefinite hang. The server side now has its own
// real request timeout (CHAT_REQUEST_TIMEOUT_MS in app.ts) so a genuinely
// stuck connection eventually fails loudly instead of hanging forever, but
// that alone still leaves a user watching a static-looking countdown with
// no way to act. This threshold is when the bubble's own wording escalates
// and a Cancel button appears, well before the server's own timeout would
// ever fire on its own. Overridable via window.__DEVLORE_TEST_CHAT_ESCALATE_MS__
// (set through page.addInitScript before navigation) so e2e coverage
// doesn't have to wait out a real 25 real seconds to exercise this path.
const CHAT_ESCALATE_AFTER_MS = window.__DEVLORE_TEST_CHAT_ESCALATE_MS__ ?? 25000;

formEl.addEventListener("submit", async (event) => {
  event.preventDefault();
  const question = inputEl.value.trim();
  if (!question || !selectedProject) {
    return;
  }

  appendMessage("user", question);
  inputEl.value = "";
  inputEl.disabled = true;

  // Two independently-timed phases in per-query mode — refreshing, then
  // asking — instead of one opaque combined wait, so a genuinely slow
  // answer (a large project's corpus can legitimately take well over a
  // minute) never looks indistinguishable from a hung request.
  let askTimer;
  const chatController = new AbortController();
  try {
    if (vaultRefreshMode === "per-query") {
      const refreshTimer = appendTimedPendingMessage("Refreshing vault…", { withVaultLink: true });
      try {
        await fetch("/api/vault/refresh", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ projectName: selectedProject }),
        });
      } catch {
        // Best-effort, same as the server's own internal per-query
        // refresh — a failed pre-sync never blocks the question.
      } finally {
        refreshTimer.stop("Refreshed vault");
      }
    }

    askTimer = appendTimedPendingMessage("Asking Claude…", {
      escalateAfterMs: CHAT_ESCALATE_AFTER_MS,
      escalatedLabel: "Still waiting on Claude…",
      onCancel: () => chatController.abort(),
    });

    const res = await fetch("/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ question, projectName: selectedProject, history }),
      signal: chatController.signal,
    });
    const data = await res.json();

    if (!res.ok) {
      throw new Error(data.error || `request failed: ${res.status}`);
    }

    // The "Asking Claude…" phase freezes in place, same as the refresh
    // phase above, rather than being overwritten — the reply lands as
    // its own new bubble, so the frozen line stays on screen as a
    // reference for how long the answer actually took.
    askTimer.stop("Asked Claude");
    appendMessage("assistant", data.reply);
    history.push({ role: "user", content: question });
    history.push({ role: "assistant", content: data.reply });

    // Refresh so the header's chat-usage figure reflects this exchange.
    loadProjects();
  } catch (error) {
    const cancelled = error.name === "AbortError";
    if (askTimer) {
      askTimer.stop(cancelled ? "Cancelled" : "Asked Claude");
    }
    appendMessage("error", cancelled ? "Cancelled — request stopped." : `Error: ${error.message}`);
  } finally {
    inputEl.disabled = false;
    inputEl.focus();
  }
});

